//! `cargo xtask codegen`: generate ruthenium-data's tables for the supported
//! game version.
//!
//! Everything comes from the official client jar pinned in ruthenium-prepare
//! (its SHA-1 is checked first):
//! - Mojang's data generator, run from that jar with `--reports`, gives the
//!   packet ids, the static registries and the block states;
//! - the jar's bytecode gives the entity-data serializer ids (see
//!   [`entity_data`]).
//!
//! Only facts go into the generated files: names and numeric ids. The files
//! are committed, so building Ruthenium needs no game files. `--check` fails
//! when they are out of date.

use std::io::{Cursor, Read as _};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use ruthenium_prepare::step;
use serde_json::Value;
use sha1::{Digest, Sha1};

use crate::jvm;

mod blocks;
mod classfile;
mod entity_data;
mod packets;
mod registries;
mod rust;

/// The generated module for version `x.y` is `<DATA_SRC>/vx_y/`.
const DATA_SRC: &str = "crates/ruthenium-data/src";

/// Bump when the data generator's invocation changes, to rerun it.
const DATAGEN_STEP: &str = "codegen-datagen-v1";

/// A generated file: its module doc line and its body.
struct Generated {
    doc: String,
    body: String,
}

pub fn run(root: &Path, args: &[String]) -> ExitCode {
    match run_inner(root, args) {
        Ok(code) => code,
        Err(e) => {
            eprintln!("codegen: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run_inner(root: &Path, args: &[String]) -> Result<ExitCode, String> {
    let mut check = false;
    let mut reports: Option<PathBuf> = None;
    let mut deps: Option<PathBuf> = None;
    let mut java = jvm::tool("java");
    let mut it = args.iter();
    while let Some(arg) = it.next() {
        if arg == "--check" {
            check = true;
            continue;
        }
        let value = it.next().ok_or_else(|| format!("{arg} needs a value"))?;
        match arg.as_str() {
            "--reports" => reports = Some(PathBuf::from(value)),
            // The data generator runs in another folder: make paths absolute.
            "--deps" => deps = Some(absolute(value)?),
            "--java" => java = absolute(value)?,
            other => return Err(format!("unknown argument {other:?}")),
        }
    }

    let version = ruthenium_prepare::supported_version();
    let jar_path = client_jar(root, deps.as_deref())?;
    let jar = std::fs::read(&jar_path).map_err(|e| format!("{}: {e}", jar_path.display()))?;
    let sha1 = hex(&Sha1::digest(&jar));
    if sha1 != version.client_jar.sha1 {
        return Err(format!(
            "{}: SHA-1 {sha1} is not the pinned {} client jar ({})",
            jar_path.display(),
            version.id,
            version.client_jar.sha1
        ));
    }
    let mut zip = zip::ZipArchive::new(Cursor::new(&jar))
        .map_err(|e| format!("{}: {e}", jar_path.display()))?;
    let version_json = jar_entry(&mut zip, "version.json")?;
    let version_json: Value =
        serde_json::from_slice(&version_json).map_err(|e| format!("version.json: {e}"))?;
    let serializers = jar_entry(&mut zip, entity_data::CLASS)?;

    let reports = match reports {
        Some(r) => r,
        None => datagen(root, &java, deps.as_deref(), &sha1)?,
    };
    let report = |name: &str| -> Result<Value, String> {
        let path = reports.join(name);
        let text =
            std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))
    };
    let registries_json = report("registries.json")?;

    let module = format!("v{}", version.id.replace('.', "_"));
    let files = [
        ("mod.rs", module_root(version.id)),
        (
            "version.rs",
            version_facts(&version_json, version.id, &sha1)?,
        ),
        ("packets.rs", packets::generate(&report("packets.json")?)?),
        ("registries.rs", registries::generate(&registries_json)?),
        (
            "blocks.rs",
            blocks::generate(&report("blocks.json")?, &registries_json)?,
        ),
        ("entity_data.rs", entity_data::generate(&serializers)?),
    ];

    let dir = root.join(DATA_SRC).join(&module);
    let mut changed = Vec::new();
    for (name, file) in &files {
        let source = format!(
            "//! {}\n//!\n//! @generated by `cargo xtask codegen` from the official {} client jar.\n//! Facts only: names and numeric ids. Do not edit by hand.\n\n{}",
            file.doc, version.id, file.body
        );
        let text = rust::format(root, &source)?;
        let path = dir.join(name);
        if std::fs::read_to_string(&path).ok().as_deref() == Some(text.as_str()) {
            continue;
        }
        if !check {
            std::fs::create_dir_all(&dir).map_err(|e| format!("{}: {e}", dir.display()))?;
            std::fs::write(&path, text).map_err(|e| format!("{}: {e}", path.display()))?;
        }
        changed.push(path);
    }

    let shown = |p: &PathBuf| p.strip_prefix(root).unwrap_or(p).display().to_string();
    if check {
        if changed.is_empty() {
            println!("codegen: {DATA_SRC}/{module} is up to date");
            return Ok(ExitCode::SUCCESS);
        }
        eprintln!("codegen: out of date (run `cargo xtask codegen`):");
        for p in &changed {
            eprintln!("  {}", shown(p));
        }
        return Ok(ExitCode::FAILURE);
    }
    for p in &changed {
        println!("wrote {}", shown(p));
    }
    println!(
        "codegen: {} file(s) in {DATA_SRC}/{module}, {} changed",
        files.len(),
        changed.len()
    );
    let lib = std::fs::read_to_string(root.join(DATA_SRC).join("lib.rs")).unwrap_or_default();
    if !lib.contains(&format!("pub mod {module};")) {
        println!("codegen: add `pub mod {module};` to {DATA_SRC}/lib.rs");
    }
    Ok(ExitCode::SUCCESS)
}

/// The client jar: `<deps>/client.jar`, else the local reference copy, else
/// `cache/compile-deps/client.jar`. Same order as [`jvm::game_classpath`].
fn client_jar(root: &Path, deps: Option<&Path>) -> Result<PathBuf, String> {
    if let Some(d) = deps {
        return Ok(d.join("client.jar"));
    }
    [
        root.join("reference/26.3/jars/client.jar"),
        root.join("cache/compile-deps/client.jar"),
    ]
    .into_iter()
    .find(|p| p.is_file())
    .ok_or_else(|| {
        "no client jar: run `cargo xtask fetch-compile-deps` or pass --deps <folder>".into()
    })
}

fn jar_entry(zip: &mut zip::ZipArchive<Cursor<&Vec<u8>>>, name: &str) -> Result<Vec<u8>, String> {
    let mut entry = zip
        .by_name(name)
        .map_err(|e| format!("client jar: {name}: {e}"))?;
    let mut bytes = Vec::new();
    entry
        .read_to_end(&mut bytes)
        .map_err(|e| format!("client jar: {name}: {e}"))?;
    Ok(bytes)
}

/// Runs `net.minecraft.data.Main --reports` from the client jar into
/// `cache/codegen/datagen`, unless it already ran for this jar. Returns the
/// reports folder.
fn datagen(
    root: &Path,
    java: &Path,
    deps: Option<&Path>,
    jar_sha1: &str,
) -> Result<PathBuf, String> {
    let base = root.join("cache/codegen");
    let out = base.join("datagen");
    let key = step::key(&[DATAGEN_STEP, jar_sha1]);
    if !step::is_current(&out, &key) {
        let classpath = jvm::game_classpath(root, deps)?;
        let work = base.join("work");
        let log = base.join("datagen.log");
        std::fs::create_dir_all(&work).map_err(|e| format!("{}: {e}", work.display()))?;
        println!(
            "codegen: running Mojang's data generator with {}",
            java.display()
        );
        step::run(
            &out,
            &key,
            |tmp| -> Result<(), Box<dyn std::error::Error>> {
                let file = std::fs::File::create(&log)?;
                let status = Command::new(java)
                    .arg("-cp")
                    .arg(&classpath)
                    .arg("net.minecraft.data.Main")
                    .arg("--reports")
                    .arg("--output")
                    .arg(tmp)
                    .current_dir(&work)
                    .stdin(Stdio::null())
                    .stdout(file.try_clone()?)
                    .stderr(file)
                    .status()
                    .map_err(|e| format!("running {}: {e}", java.display()))?;
                if !status.success() {
                    return Err(format!(
                        "the data generator exited with {status}; see {}",
                        log.display()
                    )
                    .into());
                }
                Ok(())
            },
        )
        .map_err(|e| e.to_string())?;
    }
    Ok(out.join("reports"))
}

fn module_root(id: &str) -> Generated {
    Generated {
        doc: format!("Minecraft: Java Edition {id}."),
        body: "pub mod blocks;\npub mod entity_data;\npub mod packets;\npub mod registries;\npub mod version;\n\npub use blocks::BlockState;\npub use registries::Block;\n".into(),
    }
}

fn version_facts(json: &Value, id: &str, jar_sha1: &str) -> Result<Generated, String> {
    let num = |v: &Value, what: &str| {
        v.as_u64()
            .ok_or_else(|| format!("version.json: {what} is not a number"))
    };
    if json["id"].as_str() != Some(id) {
        return Err(format!(
            "version.json: id is {}, expected {id:?}",
            json["id"]
        ));
    }
    let pack = &json["pack_version"];
    let mut body = String::new();
    body += &format!("/// The version name.\npub const ID: &str = {id:?};\n\n");
    body += &format!(
        "/// The protocol version sent in the handshake.\npub const PROTOCOL_VERSION: i32 = {};\n\n",
        num(&json["protocol_version"], "protocol_version")?
    );
    body += &format!(
        "/// The world (data) version.\npub const WORLD_VERSION: i32 = {};\n\n",
        num(&json["world_version"], "world_version")?
    );
    body += &format!(
        "/// Resource pack format (major, minor).\npub const RESOURCE_PACK_VERSION: (u32, u32) = ({}, {});\n\n",
        num(&pack["resource_major"], "resource_major")?,
        num(&pack["resource_minor"], "resource_minor")?
    );
    body += &format!(
        "/// Data pack format (major, minor).\npub const DATA_PACK_VERSION: (u32, u32) = ({}, {});\n\n",
        num(&pack["data_major"], "data_major")?,
        num(&pack["data_minor"], "data_minor")?
    );
    body += &format!(
        "/// SHA-1 of the client jar these tables were generated from.\npub const CLIENT_JAR_SHA1: &str = {jar_sha1:?};\n"
    );
    Ok(Generated {
        doc: "Version facts from the client jar's `version.json`.".into(),
        body,
    })
}

fn absolute(path: &str) -> Result<PathBuf, String> {
    std::path::absolute(path).map_err(|e| format!("{path}: {e}"))
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}
